-- Module 33: evidence-bound AI Business Advisor.
create table public.advisor_business_query_definitions(
 key text primary key check(key in('customers_not_returned','reorder_candidates','product_sales_comparison')),
 label text not null,description text not null,required_permission text not null references public.permissions(key),
 date_behavior text not null check(date_behavior in('inactive_before','current_snapshot','period_comparison')),is_enabled boolean not null default true,created_at timestamptz not null default now()
);
insert into public.advisor_business_query_definitions(key,label,description,required_permission,date_behavior)values
('customers_not_returned','Customers who have not returned','Customers with at least one recorded transaction whose last recorded purchase is before the cutoff date.','crm.read','inactive_before'),
('reorder_candidates','Reorder candidates','Tracked products whose current accessible stock is at or below the greater of their configured reorder level and low-stock threshold. Suggested quantity only fills that configured target.','inventory.read','current_snapshot'),
('product_sales_comparison','Product sales comparison','Net units by product in the selected period compared with the immediately preceding period of equal length.','sales.read','period_comparison');
alter table public.advisor_business_query_definitions enable row level security;
create policy advisor_business_query_registry_read on public.advisor_business_query_definitions for select to authenticated using(is_enabled);
revoke all on public.advisor_business_query_definitions from public,anon,authenticated;grant select on public.advisor_business_query_definitions to authenticated;

create function public.query_advisor_business_data(requested_organization_id uuid,requested_query_key text,requested_date_from date default null,requested_date_to date default null,requested_branch_id uuid default null,requested_limit integer default 10)returns jsonb
language plpgsql security definer set search_path='' as $$
declare definition public.advisor_business_query_definitions%rowtype;today_ph date:=(now()at time zone'Asia/Manila')::date;date_from date;date_to date;from_at timestamptz;to_at timestamptz;previous_from timestamptz;rows jsonb:='[]'::jsonb;period_days integer;
begin
 select*into definition from public.advisor_business_query_definitions where key=requested_query_key and is_enabled;
 if auth.uid()is null or definition.key is null then raise exception'Unknown or unavailable business query.'using errcode='22023';end if;
 if requested_limit not between 1 and 25 then raise exception'Business query limit must be between 1 and 25.'using errcode='22023';end if;
 if requested_branch_id is not null and not private.analytics_branch_allowed(requested_organization_id,requested_branch_id,definition.required_permission)then raise exception'Permission denied.'using errcode='42501';end if;
 if requested_branch_id is null and(not private.can_business_permission(requested_organization_id,'report.read',null)or not private.can_business_permission(requested_organization_id,definition.required_permission,null))then raise exception'Permission denied.'using errcode='42501';end if;
 if definition.date_behavior='current_snapshot'and(requested_date_from is not null or requested_date_to is not null)then raise exception'This business query is a current snapshot and does not accept date filters.'using errcode='22023';end if;
 if definition.date_behavior='inactive_before'then date_from:=coalesce(requested_date_from,today_ph-30);date_to:=null;from_at:=date_from::timestamp at time zone'Asia/Manila';
 elsif definition.date_behavior='period_comparison'then date_from:=coalesce(requested_date_from,date_trunc('month',today_ph)::date);date_to:=coalesce(requested_date_to,today_ph);if date_from>date_to or date_to-date_from>365 then raise exception'Date range must be ordered and no longer than 366 days.'using errcode='22023';end if;from_at:=date_from::timestamp at time zone'Asia/Manila';to_at:=(date_to+1)::timestamp at time zone'Asia/Manila';period_days:=date_to-date_from+1;previous_from:=(date_from-period_days)::timestamp at time zone'Asia/Manila';end if;
 if requested_query_key='customers_not_returned'then
  select coalesce(jsonb_agg(jsonb_build_object('customerId',ranked.id,'name',ranked.name,'mobile',ranked.phone,'lastPurchase',ranked.last_transaction_at,'daysSinceLastPurchase',today_ph-(ranked.last_transaction_at at time zone'Asia/Manila')::date,'transactionCount',ranked.transaction_count)order by ranked.last_transaction_at,ranked.name),'[]'::jsonb)into rows from(select customer.id,customer.name,customer.phone,customer.last_transaction_at,customer.transaction_count from public.sales_customers customer where customer.organization_id=requested_organization_id and customer.transaction_count>0 and customer.last_transaction_at<from_at and private.analytics_branch_allowed(requested_organization_id,customer.branch_id,definition.required_permission)and(requested_branch_id is null or customer.branch_id=requested_branch_id)order by customer.last_transaction_at,customer.name limit requested_limit)ranked;
 elsif requested_query_key='reorder_candidates'then
  select coalesce(jsonb_agg(jsonb_build_object('productName',ranked.product_name,'variantName',ranked.variant_name,'sku',ranked.sku,'quantityOnHand',ranked.quantity_on_hand,'lowStockThreshold',ranked.low_stock_threshold,'reorderLevel',ranked.reorder_level,'suggestedQuantity',greatest(ranked.target_quantity-ranked.quantity_on_hand,0))order by ranked.quantity_on_hand,ranked.product_name),'[]'::jsonb)into rows from(select product.name product_name,variant.name variant_name,variant.sku,item.low_stock_threshold,item.reorder_level,greatest(item.low_stock_threshold,item.reorder_level)target_quantity,sum(balance.quantity)quantity_on_hand from public.inventory_items item join public.product_variants variant on variant.id=item.product_variant_id and variant.organization_id=item.organization_id join public.products product on product.id=variant.product_id and product.organization_id=variant.organization_id join public.stock_balances balance on balance.inventory_item_id=item.id and balance.organization_id=item.organization_id join public.inventory_locations location on location.id=balance.location_id and location.organization_id=balance.organization_id where item.organization_id=requested_organization_id and item.is_tracked and product.status='active'and variant.status='active'and private.analytics_branch_allowed(requested_organization_id,location.branch_id,definition.required_permission)and(requested_branch_id is null or location.branch_id=requested_branch_id)group by product.name,variant.name,variant.sku,item.low_stock_threshold,item.reorder_level having sum(balance.quantity)<=greatest(item.low_stock_threshold,item.reorder_level)order by quantity_on_hand,product.name limit requested_limit)ranked;
 elsif requested_query_key='product_sales_comparison'then
  select coalesce(jsonb_agg(jsonb_build_object('productName',ranked.product_name,'sku',ranked.sku,'currentUnits',ranked.current_units,'previousUnits',ranked.previous_units,'unitChange',ranked.current_units-ranked.previous_units,'changePercent',case when ranked.previous_units=0 then null else round((ranked.current_units-ranked.previous_units)/ranked.previous_units*100,2)end)order by ranked.current_units-ranked.previous_units,ranked.product_name),'[]'::jsonb)into rows from(select line.product_name,line.sku,coalesce(sum(greatest(line.quantity-line.returned_quantity,0))filter(where sale.created_at>=from_at and sale.created_at<to_at),0)current_units,coalesce(sum(greatest(line.quantity-line.returned_quantity,0))filter(where sale.created_at>=previous_from and sale.created_at<from_at),0)previous_units from public.sales_lines line join public.sales_transactions sale on sale.id=line.sale_id and sale.organization_id=line.organization_id where line.organization_id=requested_organization_id and sale.created_at>=previous_from and sale.created_at<to_at and sale.status not in('suspended','voided')and private.analytics_branch_allowed(requested_organization_id,sale.branch_id,definition.required_permission)and(requested_branch_id is null or sale.branch_id=requested_branch_id)group by line.product_name,line.sku order by coalesce(sum(greatest(line.quantity-line.returned_quantity,0))filter(where sale.created_at>=from_at and sale.created_at<to_at),0)-coalesce(sum(greatest(line.quantity-line.returned_quantity,0))filter(where sale.created_at>=previous_from and sale.created_at<from_at),0),line.product_name limit requested_limit)ranked;
 end if;
 return jsonb_build_object('queryKey',definition.key,'label',definition.label,'definition',definition.description,'rows',rows,'dateBehavior',definition.date_behavior,'period',case when definition.date_behavior='inactive_before'then jsonb_build_object('inactiveBefore',date_from,'timezone','Asia/Manila')when definition.date_behavior='period_comparison'then jsonb_build_object('dateFrom',date_from,'dateTo',date_to,'timezone','Asia/Manila')else null end,'branchId',requested_branch_id,'calculatedAt',now());
exception when invalid_text_representation or numeric_value_out_of_range then raise exception'Invalid business query.'using errcode='22023';end$$;
revoke all on function public.query_advisor_business_data(uuid,text,date,date,uuid,integer)from public,anon;grant execute on function public.query_advisor_business_data(uuid,text,date,date,uuid,integer)to authenticated;

create table public.ai_advisor_conversations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,title text not null check(char_length(btrim(title))between 1 and 160),branch_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict
);
create table public.ai_advisor_messages(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,conversation_id uuid not null,role text not null check(role in('assistant','user')),content text not null check(char_length(btrim(content))between 1 and 4000),response_data jsonb,metric_evidence jsonb,business_query_evidence jsonb,created_at timestamptz not null default clock_timestamp(),foreign key(conversation_id,organization_id)references public.ai_advisor_conversations(id,organization_id)on delete cascade,
 check((role='user'and response_data is null and metric_evidence is null and business_query_evidence is null)or(role='assistant'and jsonb_typeof(response_data)='object'and jsonb_typeof(metric_evidence)='array'and jsonb_typeof(business_query_evidence)='array'))
);
create table public.ai_advisor_events(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,conversation_id uuid not null,assistant_message_id uuid,event text not null check(event in('conversation_started','answered','insufficient_data','clarification_requested')),actor_id uuid not null references auth.users(id),metric_keys text[]not null default'{}',business_query_keys text[]not null default'{}',created_at timestamptz not null default clock_timestamp(),foreign key(conversation_id,organization_id)references public.ai_advisor_conversations(id,organization_id)on delete cascade,foreign key(assistant_message_id)references public.ai_advisor_messages(id)on delete set null
);
create index ai_advisor_conversations_history_idx on public.ai_advisor_conversations(organization_id,created_by,updated_at desc);create index ai_advisor_messages_thread_idx on public.ai_advisor_messages(organization_id,conversation_id,created_at,id);create trigger set_updated_at before update on public.ai_advisor_conversations for each row execute function private.set_updated_at();

create function public.start_ai_advisor_conversation(requested_organization_id uuid,requested_branch_id uuid default null)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=auth.uid();conversation_key uuid;message_key uuid;begin if actor is null or not private.can_business_permission(requested_organization_id,'ai.read',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;insert into public.ai_advisor_conversations(organization_id,title,branch_id,created_by)values(requested_organization_id,'New advisor conversation',requested_branch_id,actor)returning id into conversation_key;insert into public.ai_advisor_messages(organization_id,conversation_id,role,content,response_data,metric_evidence,business_query_evidence)values(requested_organization_id,conversation_key,'assistant','Ask me about sales, products, customers, inventory, expenses, or receivables. I will only use approved business metrics and clearly label what is calculated or recommended.',jsonb_build_object('sections',jsonb_build_array(jsonb_build_object('kind','fact','title','Data boundary','content','I only use approved NegosyoOS analytics and business queries.','evidence','[]'::jsonb)),'insufficientData',false,'followUpQuestions',jsonb_build_array('How much did I sell today?','What should I reorder?','What products are not selling?')),'[]','[]')returning id into message_key;insert into public.ai_advisor_events(organization_id,conversation_id,assistant_message_id,event,actor_id)values(requested_organization_id,conversation_key,message_key,'conversation_started',actor);return conversation_key;end$$;
create function public.record_ai_advisor_exchange(requested_organization_id uuid,requested_conversation_id uuid,user_question text,assistant_content text,assistant_response jsonb,metrics jsonb,business_queries jsonb,outcome text,queried_metric_keys text[],queried_business_query_keys text[])returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=auth.uid();assistant_message uuid;conversation public.ai_advisor_conversations%rowtype;begin select*into conversation from public.ai_advisor_conversations where id=requested_conversation_id and organization_id=requested_organization_id for update;if actor is null or conversation.id is null or conversation.created_by<>actor or not private.can_business_permission(requested_organization_id,'ai.read',conversation.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if outcome not in('answered','insufficient_data','clarification_requested')or char_length(btrim(user_question))not between 3 and 2000 or char_length(btrim(assistant_content))not between 1 and 4000 or jsonb_typeof(assistant_response)<>'object'or jsonb_typeof(assistant_response->'sections')<>'array'or jsonb_typeof(assistant_response->'followUpQuestions')<>'array'or jsonb_typeof(metrics)<>'array'or jsonb_typeof(business_queries)<>'array'then raise exception'Invalid advisor exchange.'using errcode='22023';end if;insert into public.ai_advisor_messages(organization_id,conversation_id,role,content)values(requested_organization_id,requested_conversation_id,'user',btrim(user_question));insert into public.ai_advisor_messages(organization_id,conversation_id,role,content,response_data,metric_evidence,business_query_evidence)values(requested_organization_id,requested_conversation_id,'assistant',btrim(assistant_content),assistant_response,metrics,business_queries)returning id into assistant_message;update public.ai_advisor_conversations set title=case when title='New advisor conversation'then left(btrim(user_question),160)else title end where id=requested_conversation_id;insert into public.ai_advisor_events(organization_id,conversation_id,assistant_message_id,event,actor_id,metric_keys,business_query_keys)values(requested_organization_id,requested_conversation_id,assistant_message,outcome,actor,queried_metric_keys,queried_business_query_keys);end$$;

alter table public.ai_advisor_conversations enable row level security;alter table public.ai_advisor_messages enable row level security;alter table public.ai_advisor_events enable row level security;
create policy ai_advisor_conversations_owner_read on public.ai_advisor_conversations for select to authenticated using(created_by=auth.uid()and private.can_business_permission(organization_id,'ai.read',branch_id));
create policy ai_advisor_messages_owner_read on public.ai_advisor_messages for select to authenticated using(exists(select 1 from public.ai_advisor_conversations conversation where conversation.id=conversation_id and conversation.organization_id=ai_advisor_messages.organization_id and conversation.created_by=auth.uid()and private.can_business_permission(conversation.organization_id,'ai.read',conversation.branch_id)));
create policy ai_advisor_events_owner_read on public.ai_advisor_events for select to authenticated using(exists(select 1 from public.ai_advisor_conversations conversation where conversation.id=conversation_id and conversation.organization_id=ai_advisor_events.organization_id and conversation.created_by=auth.uid()and private.can_business_permission(conversation.organization_id,'ai.read',conversation.branch_id)));
revoke all on public.ai_advisor_conversations,public.ai_advisor_messages,public.ai_advisor_events from public,anon,authenticated;grant select on public.ai_advisor_conversations,public.ai_advisor_messages,public.ai_advisor_events to authenticated;
revoke all on function public.start_ai_advisor_conversation(uuid,uuid),public.record_ai_advisor_exchange(uuid,uuid,text,text,jsonb,jsonb,jsonb,text,text[],text[])from public,anon;grant execute on function public.start_ai_advisor_conversation(uuid,uuid),public.record_ai_advisor_exchange(uuid,uuid,text,text,jsonb,jsonb,jsonb,text,text[],text[])to authenticated;
comment on function public.query_advisor_business_data(uuid,text,date,date,uuid,integer)is'Allowlisted advisor query boundary. Arbitrary SQL, tables, fields, and predicates are not accepted.';
comment on table public.ai_advisor_messages is'Per-user Business conversations with the exact approved metric and query evidence used for every assistant response.';
